/** Project lat/lng into the map viewBox. */
export function sgProject(lat: number, lng: number): { x: number; y: number } {
  const scale = SG_VIEWBOX.w / (SG_BOUNDS.maxLng - SG_BOUNDS.minLng);
  const cos = Math.cos((1.35 * Math.PI) / 180);
  return { x: (lng - SG_BOUNDS.minLng) * scale, y: ((SG_BOUNDS.maxLat - lat) * scale) / cos };
}
